-- ── Ownership flows down the tree ─────────────────────────────────────────────
-- A node inherits the module of its nearest bound ancestor, so unit_id becomes a
-- complete "which module owns this topic" index rather than a set of roots. The
-- 75 nodes left NULL after this are the reference tree the courses do not teach
-- (the shared word-class strand GN:KLM, the bāb wrappers above each module) —
-- they belong to the discipline, not to a module, and the TOC shows them as such.
UPDATE ar_grammar_node SET unit_id = (
  WITH RECURSIVE owned(id, unit_id) AS (
    SELECT id, unit_id FROM ar_grammar_node WHERE unit_id IS NOT NULL
    UNION
    SELECT c.id, o.unit_id FROM ar_grammar_node c
      JOIN owned o ON c.parent_id = o.id
     WHERE c.unit_id IS NULL
  )
  SELECT o.unit_id FROM owned o WHERE o.id = ar_grammar_node.id LIMIT 1
) WHERE unit_id IS NULL;
